//! Exact saved initial deployment LOOKUP identity only. No proof approval/RPC.
use anyhow::{ensure,Result};use std::{env,fs,io::Write};use plonky2::field::goldilocks_field::GoldilocksField as F;use psy_client_data::config::store_config::PsyHasher;use psy_provider::request::QDeployContractRPCRequest;use psy_crypto::hash::tx_hash::compute_deploy_contract_content_hash;use sha2::{Digest,Sha256};
fn main()->Result<()>{let a=env::args().collect::<Vec<_>>();ensure!(a.len()==3,"SAVED_INITIAL_REQUEST FRESH_REPORT");let bytes=fs::read(&a[1])?;let r:QDeployContractRPCRequest<F>=serde_json::from_slice(&bytes)?;r.deploy_contract.validate_shape()?;let d=r.deploy_contract.deploy_contract.into_with_whitelist_root::<PsyHasher>()?;let hash=compute_deploy_contract_content_hash(&d.deployer.to_le_bytes(),&d.function_whitelist_root.to_le_bytes(),d.code_definition.state_tree_height as u64);let value=serde_json::json!({"requestSha256":format!("{:x}",Sha256::digest(&bytes)),"expectedContentHash":hash.iter().map(|b|format!("{b:02x}")).collect::<String>(),"deployer":d.deployer.to_string(),"functionTreeRoot":d.function_whitelist_root.to_string(),"codeRoot":d.code_root.to_string(),"stateTreeHeight":d.code_definition.state_tree_height,"initialProofVerified":false,"scope":"lookup identity only; content hash is not a unique occurrence or layout authorization","broadcast":false});let mut out=fs::OpenOptions::new().write(true).create_new(true).open(&a[2])?;out.write_all(&serde_json::to_vec_pretty(&value)?)?;out.sync_all()?;Ok(())}
